package io.github.sen2maker.buildingwebviewer.preview;
import android.app.*;
import android.os.*;
import android.content.*;
import android.graphics.*;
import android.net.Uri;
import android.opengl.GLSurfaceView;
import android.view.*;
import android.widget.*;
import org.json.*;
import java.io.*;
import java.util.*;
import java.util.concurrent.*;
/** App-only, read-only full Gaussian viewer on its own rendering surface. */
public class NativeGaussianActivity extends Activity implements NativeGaussianRenderer.Listener {
 static final int SAVE_IMAGE=3101;static final String[] REQUIRED={"x","y","z"};
 final ExecutorService io=Executors.newSingleThreadExecutor();final Handler main=new Handler(Looper.getMainLooper());
 GLSurfaceView surface;NativeGaussianRenderer renderer;TextView status;ProgressBar progress;Button capture,diagnose;String projectId;volatile boolean closed;boolean english;File screenshotFile;JSONObject lastReport;int fingers;float lastX,lastY,lastSpan;
 final Runnable restoreQuality=()->{if(surface!=null&&!closed)surface.requestRender();};
 String word(String zh,String en){return english?en:zh;}
 int dp(float n){return Math.round(n*getResources().getDisplayMetrics().density);}
 Button button(LinearLayout row,String zh,String en,Runnable action){Button b=new Button(this);b.setText(word(zh,en));b.setTextSize(13);b.setMinWidth(0);b.setMinimumWidth(0);b.setPadding(dp(8),0,dp(8),0);row.addView(b,new LinearLayout.LayoutParams(0,dp(46),1));b.setOnClickListener(v->action.run());return b;}
 @Override public void onCreate(Bundle saved){super.onCreate(saved);english="en".equals(getIntent().getStringExtra("lang"));projectId=getIntent().getStringExtra("project");getWindow().addFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);
  LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setBackgroundColor(Color.rgb(244,249,247));root.setOnApplyWindowInsetsListener((view,insets)->{root.setPadding(insets.getSystemWindowInsetLeft(),insets.getSystemWindowInsetTop(),insets.getSystemWindowInsetRight(),insets.getSystemWindowInsetBottom());return insets.consumeSystemWindowInsets();});
  LinearLayout header=new LinearLayout(this);header.setGravity(Gravity.CENTER_VERTICAL);Button back=new Button(this);back.setText("‹");back.setTextSize(28);header.addView(back,new LinearLayout.LayoutParams(dp(48),dp(48)));back.setOnClickListener(v->finish());TextView title=new TextView(this);title.setText(word("高斯 · 原生只读查看","Gaussian · native read-only"));title.setTextColor(Color.rgb(32,72,62));title.setTextSize(17);header.addView(title,new LinearLayout.LayoutParams(0,dp(48),1));root.addView(header);
  status=new TextView(this);status.setText(word("正在读取完整高斯…","Reading full Gaussian data…"));status.setTextSize(12);status.setPadding(dp(12),dp(4),dp(12),dp(4));root.addView(status);progress=new ProgressBar(this,null,android.R.attr.progressBarStyleHorizontal);progress.setMax(100);progress.setIndeterminate(true);root.addView(progress,new LinearLayout.LayoutParams(-1,dp(6)));
  surface=new GLSurfaceView(this);surface.setEGLContextClientVersion(3);surface.setEGLConfigChooser(8,8,8,0,0,0);surface.setPreserveEGLContextOnPause(true);renderer=new NativeGaussianRenderer(this,surface,this);surface.setRenderer(renderer);surface.setRenderMode(GLSurfaceView.RENDERMODE_WHEN_DIRTY);root.addView(surface,new LinearLayout.LayoutParams(-1,0,1));surface.setOnTouchListener((v,e)->touch(e));
  LinearLayout views=new LinearLayout(this);button(views,"立体","3D",()->renderer.preset(0));button(views,"俯视","Top",()->renderer.preset(1));button(views,"正面","Front",()->renderer.preset(2));button(views,"适应","Fit",()->{renderer.fit();surface.requestRender();});root.addView(views);
  LinearLayout tools=new LinearLayout(this);capture=button(tools,"截屏保存","Save image",()->{capture.setEnabled(false);status.setText(word("正在生成完整画质截图…","Capturing at full quality…"));renderer.capture();});capture.setEnabled(false);diagnose=button(tools,"诊断","Diagnostics",this::diagnostics);diagnose.setEnabled(false);button(tools,"兼容查看","Compatibility",()->{setResult(RESULT_OK,new Intent().putExtra("compatibility",true));finish();});root.addView(tools);setContentView(root);
  io.execute(()->{try{ProjectStore store=new ProjectStore(this);JSONArray keys=new JSONArray(getIntent().getStringExtra("keys"));List<File> files=authorizedFiles(store,projectId,keys);ActivityManager.MemoryInfo memory=new ActivityManager.MemoryInfo();((ActivityManager)getSystemService(ACTIVITY_SERVICE)).getMemoryInfo(memory);long budget=Math.max(256L*1024*1024,Math.min(768L*1024*1024,memory.availMem/3));NativeGaussianData d=NativeGaussianData.read(files,budget,(done,total,stage)->main.post(()->{if(closed)return;progress.setIndeterminate(stage.equals("gpu"));progress.setProgress((int)((long)done*100/total));status.setText(word("正在准备完整高斯 · ","Preparing full Gaussians · ")+done+" / "+total);}));if(!closed)renderer.load(d);
   }catch(Exception|OutOfMemoryError e){error(e.getMessage()==null?"Memory allocation failed":e.getMessage());}});
 }
 static List<File> authorizedFiles(ProjectStore store,String id,JSONArray keys)throws Exception{if(keys.length()==0||keys.length()>64)throw new IOException("Choose 1 to 64 Gaussian files");JSONArray records=store.get(id).getJSONArray("files");Map<String,String> allowed=new HashMap<>();for(int i=0;i<records.length();i++){JSONObject r=records.getJSONObject(i);allowed.put(r.getString("key"),r.getString("path"));}List<File> files=new ArrayList<>();for(int i=0;i<keys.length();i++){String key=keys.getString(i);if(!allowed.containsKey(key)||!allowed.get(key).toLowerCase(Locale.ROOT).endsWith(".ply"))throw new IOException("Gaussian file is not in this project");File f=store.objectFile(key);if(!f.isFile())throw new IOException("Project file is missing");files.add(f);}return files;}
 boolean touch(MotionEvent e){int action=e.getActionMasked(),n=e.getPointerCount();if(action==MotionEvent.ACTION_UP||action==MotionEvent.ACTION_CANCEL||action==MotionEvent.ACTION_POINTER_UP){fingers=0;main.removeCallbacks(restoreQuality);main.postDelayed(restoreQuality,470);return true;}float x=e.getX(),y=e.getY(),span=0;if(n>=2){x=(e.getX(0)+e.getX(1))/2;y=(e.getY(0)+e.getY(1))/2;span=(float)Math.hypot(e.getX(0)-e.getX(1),e.getY(0)-e.getY(1));}if(action==MotionEvent.ACTION_MOVE&&fingers==n)renderer.gesture(x-lastX,y-lastY,n>=2&&lastSpan>2&&span>2?span/lastSpan:1,n>=2);fingers=n;lastX=x;lastY=y;lastSpan=span;main.removeCallbacks(restoreQuality);return true;}
 @Override public void ready(int count){main.post(()->{if(closed)return;progress.setVisibility(View.GONE);capture.setEnabled(true);diagnose.setEnabled(true);status.setText(word("完整高斯：","Full Gaussians: ")+java.text.NumberFormat.getIntegerInstance().format(count)+word(" · 单指旋转，双指缩放／平移"," · one-finger orbit, two-finger zoom/pan"));});}
 @Override public void error(String message){main.post(()->{if(closed)return;progress.setVisibility(View.GONE);capture.setEnabled(false);status.setText(word("原生查看失败，可返回使用兼容查看：","Native view failed; compatibility view remains available: ")+message);});}
 @Override public void screenshot(Bitmap bitmap){io.execute(()->{try{File dir=new File(getCacheDir(),"exports/native-gaussian-"+UUID.randomUUID());if(!dir.mkdirs())throw new IOException("Cannot create screenshot folder");File file=new File(dir,"BuildingWebViewer-Gaussian.png");try(OutputStream out=new FileOutputStream(file)){if(!bitmap.compress(Bitmap.CompressFormat.PNG,100,out))throw new IOException("Cannot encode image");}finally{bitmap.recycle();}if(closed)return;screenshotFile=file;main.post(()->{if(closed)return;capture.setEnabled(true);Intent pick=new Intent(Intent.ACTION_CREATE_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType("image/png").putExtra(Intent.EXTRA_TITLE,"BuildingWebViewer-Gaussian.png");startActivityForResult(pick,SAVE_IMAGE);});}catch(Exception e){error(e.getMessage());}});}
 @Override protected void onActivityResult(int request,int result,Intent intent){super.onActivityResult(request,result,intent);if(request!=SAVE_IMAGE)return;File file=screenshotFile;screenshotFile=null;if(result!=RESULT_OK||intent==null||file==null)return;Uri uri=intent.getData();if(uri==null)return;io.execute(()->{try(InputStream in=new FileInputStream(file);OutputStream out=getContentResolver().openOutputStream(uri)){if(out==null)throw new IOException("Cannot open image destination");byte[] b=new byte[65536];int n;while((n=in.read(b))!=-1)out.write(b,0,n);main.post(()->{if(!closed)Toast.makeText(this,word("截图已保存","Image saved"),Toast.LENGTH_SHORT).show();});}catch(Exception e){error(e.getMessage());}});}
 void diagnostics(){String[] actions={word("自动旋转采集 10 秒","Automatic orbit sample (10 seconds)"),word("手动拖动采集 10 秒","Manual sample (10 seconds)"),word("查看报告","View report")};new AlertDialog.Builder(this).setTitle(word("原生渲染诊断","Native rendering diagnostics")).setItems(actions,(dialog,index)->{if(index<2){capture.setEnabled(false);diagnose.setEnabled(false);renderer.sample(index==0);main.postDelayed(()->{if(!closed)renderer.endSample();},10000);Toast.makeText(this,word("正在采集 10 秒","Sampling for 10 seconds"),Toast.LENGTH_SHORT).show();}else showReport();}).setNegativeButton(word("关闭","Close"),null).show();}
 @Override public void sampled(JSONObject report){lastReport=report;getSharedPreferences("native-gaussian",MODE_PRIVATE).edit().putString("lastReport",report.toString()).apply();main.post(()->{if(!closed){capture.setEnabled(renderer.ready);diagnose.setEnabled(true);Toast.makeText(this,word("诊断完成，可复制报告","Sample complete; report can be copied"),Toast.LENGTH_SHORT).show();}});}
 void showReport(){String text;try{JSONObject r=lastReport!=null?lastReport:new JSONObject(getSharedPreferences("native-gaussian",MODE_PRIVATE).getString("lastReport","{}"));text=r.toString(2);}catch(Exception e){text="{}";}final String report=text;TextView view=new TextView(this);view.setTextIsSelectable(true);view.setText(report);view.setTextSize(12);view.setPadding(dp(12),dp(12),dp(12),dp(12));ScrollView scroll=new ScrollView(this);scroll.addView(view);new AlertDialog.Builder(this).setTitle(word("原生渲染报告","Native rendering report")).setView(scroll).setPositiveButton(word("复制","Copy"),(d,w)->{android.content.ClipboardManager c=(android.content.ClipboardManager)getSystemService(CLIPBOARD_SERVICE);c.setPrimaryClip(ClipData.newPlainText("BuildingWebViewer native diagnostics",report));}).setNegativeButton(word("关闭","Close"),null).show();}
 @Override protected void onResume(){super.onResume();if(surface!=null){surface.onResume();surface.requestRender();}}
 @Override protected void onPause(){if(renderer!=null)renderer.pause();if(surface!=null)surface.onPause();super.onPause();}
 @Override protected void onDestroy(){closed=true;main.removeCallbacksAndMessages(null);if(renderer!=null)renderer.destroy();io.shutdownNow();getWindow().clearFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);super.onDestroy();}
}
